import json, requests, sys

webhook_url = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "🔔 澳洲冰箱新品巡检 - 2026年6月25日 上午"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**发现 1 项变化**\n\n---\n**海信 Hisense HRCD615TBW**\n📦 615L PureFlex French Door Fridge\n🔄 库存状态变化：**Out of Stock → In Stock**\n💰 $3,299.00\n\n---\n\n**无变化品牌：**\n• 美的 Midea - 12款产品，无新增/状态变更\n• 三星 Samsung - 未发现新机型\n• LG - 未发现新机型\n• 西屋 Westinghouse - 5款精选产品无变化\n\n> MDRT580MTF45AP (413L) 仍为 Coming Soon 状态"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动巡检"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook_url, json=card, timeout=15)
result = {"status": resp.status_code, "body": resp.text}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

